def search_foods(query: str = '', category: Optional[str] = None, limit: int = 50) -> List[Dict[str, Any]]:
    """Search foods by query with intelligent multi-tier relevance ranking."""
    query = (query or '').lower().strip()

    if not query:
        if category:
            return [f for f in FOODS if f.get('category') == category][:limit]
        return FOODS[:limit]

    scored_results = []
    for food in FOODS:
        if category and food.get('category') != category:
            continue

        score = 0
        name_lower = food['name'].lower()
        food_id = food['id'].lower()
        hindi = (food.get('name_hindi') or '').lower()

        if query == food_id or query == name_lower:
            score = 100
        elif name_lower.startswith(query):
            score = 85
        elif f' {query}' in name_lower or f'({query}' in name_lower:
            score = 75
        elif query in name_lower:
            score = 65
        elif any(alias.lower() == query for alias in food.get('aliases', [])):
            score = 60
        elif any(alias.lower().startswith(query) for alias in food.get('aliases', [])):
            score = 50
        elif any(query in alias.lower() for alias in food.get('aliases', [])):
            score = 40
        elif hindi and query in hindi:
            score = 45
        elif food.get('region') and query in food['region'].lower():
            score = 25
        elif food.get('category') and query in food['category'].lower():
            score = 20

        if score > 0:
            scored_results.append((score, len(food['name']), food))

    # Sort descending by relevance score, then ascending by name length
    scored_results.sort(key=lambda x: (-x[0], x[1]))
    return [item[2] for item in scored_results[:limit]]


def get_food_by_id(food_id: str) -> Optional[Dict[str, Any]]:
    """Get a single food by ID with O(1) lookup."""
    if not food_id:
        return None
    return FOODS_BY_ID.get(food_id.strip())


def get_food_by_name(name: str) -> Optional[Dict[str, Any]]:
    """Fuzzy match food by exact name, alias, or ID."""
    if not name:
        return None
    name_lower = name.lower().strip()

    if name_lower in FOODS_BY_ID:
        return FOODS_BY_ID[name_lower]

    for food in FOODS:
        if food['name'].lower() == name_lower:
            return food
        if food.get('name_hindi') and food['name_hindi'].lower() == name_lower:
            return food
        for alias in food.get('aliases', []):
            if alias.lower() == name_lower:
                return food
    return None


def get_foods_by_category(category: str) -> List[Dict[str, Any]]:
    """Get all foods in a given category."""
    return [f for f in FOODS if f.get('category') == category]
